/**
 * Footnote: an inline atom holding its own text. Numbers are generated by a
 * CSS counter, so they renumber automatically. Clicking opens an editor.
 */
import { mergeAttributes, Node } from '@tiptap/core';
import { Plugin, PluginKey } from '@tiptap/pm/state';

declare module '@tiptap/core' {
  interface Commands<ReturnType> {
    footnote: {
      insertFootnote: (text?: string) => ReturnType;
      updateFootnote: (pos: number, text: string) => ReturnType;
      removeFootnote: (pos: number) => ReturnType;
    };
  }
}

export interface FootnoteOptions {
  onEdit: (pos: number, text: string) => void;
}

export const Footnote = Node.create<FootnoteOptions>({
  name: 'footnote',
  group: 'inline',
  inline: true,
  atom: true,
  selectable: true,

  addOptions() {
    return { onEdit: () => {} };
  },

  addAttributes() {
    return {
      text: {
        default: '',
        parseHTML: (el) => el.getAttribute('data-text') ?? el.textContent ?? '',
        renderHTML: (attrs) => ({ 'data-text': attrs.text, title: attrs.text || 'Empty footnote' }),
      },
    };
  },

  parseHTML() {
    return [{ tag: 'sup[data-footnote]' }];
  },

  renderHTML({ HTMLAttributes }) {
    return ['sup', mergeAttributes(HTMLAttributes, { 'data-footnote': '', class: 'footnote-ref', role: 'button', 'aria-label': 'Footnote' })];
  },

  renderText() {
    return '';
  },

  addCommands() {
    return {
      insertFootnote:
        (text = '') =>
        ({ commands }) =>
          commands.insertContent({ type: this.name, attrs: { text } }),
      updateFootnote:
        (pos, text) =>
        ({ tr, dispatch, state }) => {
          const node = state.doc.nodeAt(pos);
          if (!node || node.type.name !== this.name) return false;
          if (dispatch) tr.setNodeMarkup(pos, undefined, { ...node.attrs, text });
          return true;
        },
      removeFootnote:
        (pos) =>
        ({ tr, dispatch, state }) => {
          const node = state.doc.nodeAt(pos);
          if (!node || node.type.name !== this.name) return false;
          if (dispatch) tr.delete(pos, pos + node.nodeSize);
          return true;
        },
    };
  },

  addKeyboardShortcuts() {
    return {
      'Mod-Alt-f': () => {
        const ok = this.editor.commands.insertFootnote('');
        if (ok) this.options.onEdit(this.editor.state.selection.from - 1, '');
        return ok;
      },
    };
  },

  addProseMirrorPlugins() {
    const onEdit = this.options.onEdit;
    const name = this.name;
    return [
      new Plugin({
        key: new PluginKey('footnoteClick'),
        props: {
          handleClickOn(_view, _pos, node, nodePos) {
            if (node.type.name !== name) return false;
            onEdit(nodePos, String(node.attrs.text ?? ''));
            return true;
          },
        },
      }),
    ];
  },
});
